//! `gpud` client (docs/kabylake-gpu-plan.md, stage G1): the display state the
//! Intel GPU service adopted from the firmware.
//!
//! The `os.lazy.gpu.v1` stubs are generated by `midlc` from `idl/gpu.midl`;
//! this module adds the reply framing and the blocking [`Client`] alias.

use alloc::vec::Vec;

use libmessenger::{Header, Parcel, VERSION};

use super::client::Native;

/// The generated `os.lazy.gpu.v1` stubs.
pub use messenger_generated::os_lazy_gpu_v1 as wire;

/// The adopted display state and the live beam.
pub use wire::{Beam, State};

/// Registered service name.
pub const NAME: &str = wire::SERVICE_NAME;

/// The interface id every `gpud` parcel carries.
pub const INTERFACE: u64 = wire::INTERFACE_ID;

/// A parcel of `method` carrying an already-encoded `body` (request or reply).
pub fn parcel(method: u32, body: Vec<u8>) -> Parcel {
    Parcel {
        header: Header {
            version: VERSION,
            flags: 0,
            interface_id: INTERFACE,
            method,
            txn_id: 0,
            reply_to: 0,
            deadline_ns: 0,
        },
        body,
        ..Parcel::default()
    }
}

/// A blocking client of `gpud`: `Client::try_connect(Native)`. A caller that
/// must not wait on `gpud` (the compositor) bounds a call with
/// `get_beam_within`. Dropping the client releases its handle.
pub type Client = wire::Client<Native>;
